function updateStatusScreens(){if(!sharedState)return;for(const s of statusScreens){if(!s.ctx)continue;const c=s.ctx,w=c.canvas.width,h=c.canvas.height;c.fillStyle='#06111a';c.fillRect(0,0,w,h);const corrupt=sharedState.eventSpec?.kind==='corrupt';c.strokeStyle=corrupt?'#59ff9c':'#1f6772';c.strokeRect(7,7,w-14,h-14);c.fillStyle=corrupt?'#79ffab':'#68e6e2';c.font='bold 31px monospace';c.fillText(corrupt&&Math.random()<.35?'// SYS_ERR 0x7F9A':'REACTOR TELEMETRY',22,44);c.fillStyle=corrupt?'#78c990':'#91afb5';c.font='17px monospace';c.fillText(`CONDITION  ${sharedState.mode}`,22,76);c.fillText(`TEMP   ${Math.round(sharedState.temperature)} RU`,22,109);c.fillText(`STABILITY  ${Math.round(sharedState.stability)}%`,22,143);c.fillText(`OUTPUT  ${Math.round(sharedState.output)}%`,22,177);c.fillText(`SHIELD  ${Math.round(sharedState.containment)}%`,22,211);c.fillStyle=sharedState.mode==='STABLE'?'#56e7bd':'#efbb64';c.fillRect(330,194,Math.max(4,150*sharedState.stability/100),8);s.tex.needsUpdate=true}}
function addInteractable(mesh,label,action,data={}){mesh.userData.interactable=true;mesh.userData.label=label;mesh.userData.action=action;mesh.userData.data=data;interactables.push(mesh);return mesh}
function setRoomState(s){sharedState=s;if(worldBuilt)updateStatusScreens();renderGameHUD();updateReactorVisuals()}
