 core.material.color.set(color);core.material.emissive.set(color);core.material.emissiveIntensity=intensity;core.scale.setScalar(scale);core.material.opacity=.95;core.userData.inner.material.color.set(s.event==='VOID ANOMALY'?0x07010f:color);core.userData.inner.scale.setScalar(.74+Math.sin(Date.now()/420)*.05);shield.material.opacity=opacity;shield.material.color.set(color);if(frostFloor){const f=Math.max(0,Math.min(1,s.frost||0));frostFloor.material.opacity=f*.28;for(const c of frostCrystals){c.visible=f>.1;c.material.opacity=Math.max(0,(f-.08)*.72);c.scale.y=.35+f*.65}if(iceCore){iceCore.visible=f>.08;iceCore.material.opacity=f*.5;iceCore.scale.setScalar(.76+f*.24);if(s.variation==='rainbow'){iceCore.material.color.setHSL((Date.now()/24)%1,.8,.72);iceCore.material.emissive.setHSL((Date.now()/24)%1,.85,.48)}}}const breachVisual=spec?.kind==='breach';for(const frag of shieldFragments){frag.visible=!!breachVisual;frag.material.opacity=breachVisual?.35+Math.min(1,s.eventProgress||0)*.55:0}if(spaceView){const k=spec?.kind;if(k==='eclipse'){spaceView.material.color.set('#16192d');spaceView.material.opacity=.9}else if(k==='cosmic'||k==='meteor'){spaceView.material.color.set('#40577c');spaceView.material.opacity=.85}else{spaceView.material.color.set('#ffffff');spaceView.material.opacity=1}}for(const l of coreLights){l.color.set(color);l.intensity=light}if(ringGroup)ringGroup.rotation.x=Math.sin(Date.now()/3500)*.06
